from itertools import combinations

def nth(iterable, r, index, rdec, inner_div):
    pool = tuple(iterable)
    n = len(pool)
    if (r < 0) or (r > n):
        raise ValueError
    c = 1
    k = min(r, n - r)
    for i in range(1, k + 1):
        c = c * (n - k + i) // i
    if index < 0:
        index += c
    if (index < 0) or (index >= c):
        raise IndexError
    result = []
    while r:
        c, n, r = c * r // n, n - 1, (r - 1 if rdec else r + 1)
        while index >= c:
            index -= c
            if inner_div == 'n':
                c, n = c * (n - r) // n, n - 1
            else:
                c, n = c * (n - r) // (n + 1), n - 1
        result.append(pool[-1 - n])
    return tuple(result)

# Test all combinations for small cases
for rdec in [True, False]:
    for inner_div in ['n', 'n+1']:
        ok = True
        for n in range(0, 9):
            pool = tuple(range(n))
            for r in range(0, n+1):
                for idx, expected in enumerate(combinations(pool, r)):
                    try:
                        actual = nth(pool, r, idx, rdec, inner_div)
                    except Exception as e:
                        ok = False
                        print(f"rdec={rdec} inner={inner_div} n={n} r={r} idx={idx} ERROR {e}")
                        break
                    if actual != expected:
                        ok = False
                        print(f"rdec={rdec} inner={inner_div} n={n} r={r} idx={idx} got {actual} want {expected}")
                        break
                if not ok: break
            if not ok: break
        print(f"rdec={rdec} inner_div={inner_div}: {'ALL OK' if ok else 'FAIL'}")
